template:
{%- set main = value.name == "main" -%}
{%- set published = main or value.get("prefix") -%}
{%- set publisher = "studio-publish" in scope and not main -%}
{%- set base = value.get("base") or "live" -%}
<div class="studio-branch-settings" data-studio-branch-settings data-studio-mode="edit">
<dl class="studio-branch-facts">
<div><dt>Name</dt><dd>{{ value.name }}</dd></div>
<div><dt>Context</dt><dd>{{ value.rbac_context if value.rbac_context else "the site's (\"\")" }}</dd></div>
<div><dt>Parent</dt><dd>{{ value.get("parent") or "None" }}</dd></div>
{%- if published %}
<div><dt>Label</dt><dd>{{ value.get("label") or "None" }}</dd></div>
<div><dt>Description</dt><dd class="studio-branch-description">{{ value.get("description") or "None" }}</dd></div>
<div><dt>Base</dt><dd>{{ base }}</dd></div>
{%- endif %}
</dl>
{%- if not published %}
<div class="studio-branch-fields">
<span class="studio-field"><label class="studio-field-label" for="{{ input_id }}-label">Label</label><input id="{{ input_id }}-label" class="studio-field-input" type="text" name="/label" value="{{ value.get("label") or "" }}" spellcheck="false"></span>
<span class="studio-field studio-field-wide"><label class="studio-field-label" for="{{ input_id }}-description">Description</label><textarea id="{{ input_id }}-description" class="studio-field-input" name="/description" rows="3">
{{ value.get("description") or "" }}</textarea></span>
<span class="studio-field"><label class="studio-field-label" for="{{ input_id }}-base">Base</label><select id="{{ input_id }}-base" class="studio-field-input" name="/base"><option value="live"{% if base == "live" %} selected{% endif %}>live: the parent as it is now</option><option value="pinned"{% if base == "pinned" %} selected{% endif %}>pinned: the parent at the branching point</option></select></span>
</div>
{%- endif %}
{%- if value.get("prefix") is string and "prefix" in children %}
{{ children["prefix"] }}
{%- elif publisher %}
<div class="studio-field studio-field-prefix"><label class="studio-field-label" for="{{ input_id }}-prefix">Prefix</label><input id="{{ input_id }}-prefix" class="studio-field-input" type="text" name="/prefix" value="" placeholder="/segment/" spellcheck="false" autocomplete="off"></div>
{%- else %}
<div class="studio-field studio-field-prefix"><span class="studio-field-label">Prefix</span> <span data-studio-branch-prefix-text>{{ "None: main is served at the API's URLs" if main else "None: a working branch" }}</span></div>
{%- endif %}
{%- if publisher or not published %}
<div class="studio-branch-actions">
<button type="submit" class="studio-save">Save</button>
{%- if publisher and published %}
<button type="button" class="studio-unpublish" hx-put="{{ resource.href }}" hx-ext="scrud-json" data-scrud-json="fixed" data-scrud-body='{{ dict(value, prefix=none)|tojson }}' hx-swap="none">Remove the prefix</button>
{%- endif %}
</div>
{%- endif %}
{%- if publisher %}
<p class="studio-hint">A prefix publishes the branch at that URL prefix of the whole site (/segment/); changing or removing it moves or takes away those URLs.</p>
{%- endif %}
</div>
